<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import SeguimientoRecordatoriosMetricas from '@/components/seguimiento/SeguimientoRecordatoriosMetricas.vue'
import type {MetricasRecordatorios} from '@/services/seguimientoMetricasApi'
import {useAuthStore} from '@/stores/auth'
import {usePeriodoActivoStore} from '@/stores/periodoActivo'
import {getMetricas,csvMetricas,type ResumenMetricas,type ScopeMetricas,type CanalMetrica,type FilaMetrica} from '@/services/seguimientoMetricasApi'
import MetricasResumen from '@/components/seguimiento/metricas/MetricasResumen.vue'
import SeguimientoCasoDrawer from '@/components/seguimiento/SeguimientoCasoDrawer.vue'
import SeguimientoNotaDialog from '@/components/seguimiento/SeguimientoNotaDialog.vue'
import {fetchSeguimientoCaso,postSeguimientoContacto,type CasoSeguimientoDetalle,type ContactoSeguimiento} from '@/services/seguimientoRematriculaApi'
import {fechaHoraChileInput,etiquetaFechaChile,type NotaContactoPayload} from '@/utils/seguimientoNota'
const auth=useAuthStore(),periodo=usePeriodoActivoStore(),jefatura=computed(()=>[1,2].includes(Number(auth.perfil?.codigo_perfil_usuario))),hoy=fechaHoraChileInput(new Date().toISOString()).slice(0,10)
const anio=ref<number|null>(periodo.anio??null),semestre=ref<number|null>(periodo.semestre??null),desde=ref(hoy.slice(0,7)+'-01'),hasta=ref(hoy),autor=ref(auth.email??''),data=ref<ResumenMetricas|null>(null),opciones=ref<string[]>([]),cargando=ref(false),error=ref<string|null>(null),sheet=ref(false),metrica=ref('contactados'),casos=ref<{codcli:string;nombre_alumno:string|null;nombre_carrera:string|null}[]>([]),totalCasos=ref(0),pagina=ref(0),errorCasos=ref<string|null>(null)
const caso=ref<CasoSeguimientoDetalle|null>(null),bitacora=ref<ContactoSeguimiento[]>([]),drawerPeriodo=ref({anio:0,semestre:0}),nota=ref(false),guardandoNota=ref(false),errorNota=ref<string|null>(null),scopeAplicado=ref<ScopeMetricas|null>(null)
const automaticos=ref<MetricasRecordatorios|null>(null),errorAutomaticos=ref<string|null>(null)
let generation=0,caseGeneration=0
const canales:{key:CanalMetrica;label:string}[]=[{key:'correo',label:'Correo'},{key:'sms',label:'SMS'},{key:'whatsapp',label:'WhatsApp'},{key:'llamada',label:'Llamada'},{key:'nota',label:'Nota'},{key:'otros',label:'Otros (incluye presencial)'}]
async function cargar(){const id=++generation;automaticos.value=null;errorAutomaticos.value=null;cargando.value=true;error.value=null;data.value=null;casos.value=[];totalCasos.value=0;caseGeneration++;sheet.value=false
 if(!anio.value||!semestre.value){error.value='Selecciona período académico';cargando.value=false;return}
 const scope:ScopeMetricas={anio:anio.value,semestre:semestre.value,desde:desde.value,hasta:hasta.value,autor:jefatura.value?autor.value:auth.email??''}
 const [result,auto]=await Promise.all([getMetricas<{resumen:ResumenMetricas}>('resumen',scope),getMetricas<{recordatorios:MetricasRecordatorios}>('recordatorios',scope)]);if(id!==generation)return;automaticos.value=auto.data?.recordatorios??null;errorAutomaticos.value=auto.error
 if(result.error||!result.data?.resumen){error.value=result.error||'Respuesta inválida';cargando.value=false;return}data.value=result.data.resumen;scopeAplicado.value=scope;pagina.value=0
 if(jefatura.value){const all=await getMetricas<{consejeros:FilaMetrica[]}>('consejeros',scope);if(id!==generation)return;if(all.error){error.value=all.error;data.value=null;cargando.value=false;return}opciones.value=[...new Set([auth.email??'',...(all.data?.consejeros??[]).map(c=>c.autor).filter(a=>a!=='__sin_autor__')])].sort()}
 cargando.value=false;await cargarCasos()
}
async function cargarCasos(){if(!scopeAplicado.value)return;const id=++caseGeneration;errorCasos.value=null;casos.value=[];const r=await getMetricas<{casos:typeof casos.value;total:number}>('casos',scopeAplicado.value,{metrica:metrica.value,limit:'20',offset:String(pagina.value*20)});if(id!==caseGeneration)return;if(r.error){errorCasos.value=r.error;return}casos.value=r.data?.casos??[];totalCasos.value=r.data?.total??0}
async function abrirCaso(codcli:string){if(!scopeAplicado.value)return;const scope={anio:scopeAplicado.value.anio,semestre:scopeAplicado.value.semestre};const r=await fetchSeguimientoCaso(codcli,scope.anio,scope.semestre);if(r.error){errorCasos.value=r.error;return}drawerPeriodo.value=scope;caso.value=r.caso;bitacora.value=r.bitacora}
async function actualizarCaso(){if(!caso.value)return;const codcli=caso.value.codcli,r=await fetchSeguimientoCaso(codcli,drawerPeriodo.value.anio,drawerPeriodo.value.semestre);if(r.error){errorCasos.value=r.error;return}caso.value=r.caso;bitacora.value=r.bitacora;await cargar()}
async function guardarNota(payload:NotaContactoPayload){if(!caso.value)return;guardandoNota.value=true;errorNota.value=null;try{const r=await postSeguimientoContacto(caso.value.codcli,{...payload,...drawerPeriodo.value});if(r.error){errorNota.value=r.error;return}nota.value=false;await actualizarCaso()}finally{guardandoNota.value=false}}
function exportar(){if(!data.value)return;const url=URL.createObjectURL(new Blob([csvMetricas(data.value)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='metricas-seguimiento.csv';a.click();URL.revokeObjectURL(url)}
watch(()=>[periodo.anio,periodo.semestre],()=>{if(!anio.value&&periodo.anio)anio.value=periodo.anio;if(!semestre.value&&periodo.semestre)semestre.value=periodo.semestre;if(anio.value&&semestre.value&&!data.value&&!cargando.value)void cargar()},{immediate:true})
watch(metrica,()=>{pagina.value=0;void cargarCasos()})
</script>
<template>
 <main class="mx-auto min-w-0 max-w-7xl space-y-6 p-3 md:p-6">
  <header class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-xl font-bold">Métricas de seguimiento</h1><p class="text-sm text-zinc-600">{{jefatura?'Mi gestión / Jefatura':'Mi gestión'}} · America/Santiago</p></div><RouterLink to="/dashboard/bandeja-seguimiento" class="inline-flex min-h-11 items-center rounded border px-3">Abrir bandeja</RouterLink></header>
  <button class="min-h-11 rounded border px-4 md:hidden" @click="sheet=true">Período y filtros</button>
  <div v-if="sheet" class="fixed inset-0 z-40 bg-black/40 md:hidden" @click="sheet=false" />
  <form :class="sheet?'fixed inset-x-0 bottom-0 z-50 max-h-[90dvh] space-y-3 overflow-y-auto rounded-t-xl bg-white p-5 pb-[max(1rem,env(safe-area-inset-bottom))] md:static md:rounded-lg':'hidden flex-wrap items-end gap-3 rounded-lg border p-4 md:flex'" aria-label="Filtros de métricas" @submit.prevent="cargar" @keydown.esc="sheet=false">
   <button v-if="sheet" type="button" class="min-h-11 md:hidden" @click="sheet=false">Cerrar filtros</button>
   <label class="block">Año<input v-model.number="anio" type="number" min="2020" max="2099" required class="block min-h-11 w-full rounded border px-3 text-base md:w-28" /></label>
   <label class="block">Semestre<select v-model.number="semestre" required class="block min-h-11 w-full rounded border px-3 text-base"><option :value="1">1</option><option :value="2">2</option></select></label>
   <label class="block">Desde (Chile)<input v-model="desde" type="date" required class="block min-h-11 w-full rounded border px-3 text-base" /></label><label class="block">Hasta (Chile)<input v-model="hasta" type="date" required class="block min-h-11 w-full rounded border px-3 text-base" /></label>
   <label v-if="jefatura" class="block">Autor / consejero<select v-model="autor" class="block min-h-11 w-full max-w-full rounded border px-3 text-base"><option value="__todos__">Todos los autores</option><option v-for="e in opciones.length?opciones:[auth.email??'']" :key="e" :value="e">{{e}}</option></select></label>
   <button type="submit" :disabled="cargando" class="min-h-11 rounded bg-orange-600 px-4 text-white disabled:opacity-50">Aplicar</button>
  </form>
  <p v-if="cargando" role="status">Cargando métricas…</p><p v-if="error" role="alert" class="rounded border border-red-300 p-4 text-red-700">{{error}}</p>
  <SeguimientoRecordatoriosMetricas :data="automaticos" :error="errorAutomaticos" :cargando="cargando" />
  <template v-if="data&&!cargando&&!error">
   <p class="text-xs text-zinc-500">Período {{data.anio}}/{{data.semestre}} · {{data.desde}} a {{data.hasta}} · corte stock {{etiquetaFechaChile(data.calculadoEn)}} (Chile). Instrumentación desde {{etiquetaFechaChile(data.instrumentacionDesde)}} (Chile). Progreso observado: {{data.progresoActualizadoEn?etiquetaFechaChile(data.progresoActualizadoEn):'N/D'}} (Chile).</p>
   <MetricasResumen :data="data" />
   <div class="grid gap-5 md:grid-cols-2"><section class="rounded-lg border p-4"><h2 class="mb-3 font-semibold">Contactos por canal (rango)</h2><div v-for="c in canales" :key="c.key" class="mb-3"><div class="flex justify-between text-sm"><span>{{c.label}}</span><strong>{{data.canales[c.key]}}</strong></div><div class="h-2 rounded bg-zinc-100"><div class="h-2 rounded bg-orange-500" :style="{width:`${data.contactos?data.canales[c.key]/data.contactos*100:0}%`}" /></div></div></section><section class="rounded-lg border p-4"><h2 class="mb-3 font-semibold">Serie diaria de contactos (Chile)</h2><p v-if="!data.serie.length">Sin contactos en el rango</p><div class="max-h-72 overflow-y-auto"><div v-for="dia in data.serie" :key="dia.dia" class="flex justify-between border-b py-2 text-sm"><span>{{dia.dia}}</span><strong>{{dia.contactos}}</strong></div></div></section></div>
   <section v-if="jefatura" class="space-y-3"><h2 class="font-semibold">Por autor — no es ranking causal</h2><p class="text-xs">Casos distintos por autor no son sumables. Sin autor en un hito se conserva sin asignación ficticia.</p><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><article v-for="c in data.consejeros" :key="c.autor" class="min-w-0 rounded-lg border p-4"><h3 class="break-all font-semibold">{{c.autor==='__sin_autor__'?'Sin autor registrado':c.autor}}</h3><p>{{c.contactos}} contactos · {{c.casosContactados}} casos</p><p>Respuesta {{c.respuesta.tasa===null?'N/D':`${c.respuesta.tasa}%`}} ({{c.respuesta.numerador}}/{{c.respuesta.denominador}}) <span v-if="c.respuesta.parcial">· parcial</span></p><p class="text-xs">Cobertura {{c.respuesta.cobertura}}% · históricos {{c.respuesta.historicos}}</p><p>Pendientes {{c.pendientes}} · vencidas {{c.vencidas}}</p><p>Completadas {{c.completadas}} · canceladas {{c.canceladas}}</p><p>Movidos a matriculado {{c.matriculadosDetectados??'N/D'}}</p></article></div></section>
   <button class="min-h-11 rounded border px-4" @click="exportar">Exportar agregados CSV (sin datos de alumnos)</button>
   <section class="space-y-3 rounded-lg border p-4"><h2 class="font-semibold">Casos de la métrica</h2><p class="text-xs">Solo casos aún accesibles en tu cartera vigente; el total puede diferir del agregado histórico por autor. El drawer usa el período seleccionado aquí.</p><select v-model="metrica" aria-label="Métrica para ver casos" class="min-h-11 max-w-full rounded border px-3 text-base"><option value="contactados">Contactados en rango</option><option value="matriculados_actuales">Matriculados actuales con gestión del autor</option><option value="pendientes">Pendientes actuales</option><option value="vencidas">Vencidas actuales</option><option value="completadas">Completadas en rango</option><option value="matriculados_detectados">Movidos a matriculado en rango</option></select><p v-if="errorCasos" role="alert" class="text-red-700">{{errorCasos}}</p><ul class="space-y-2"><li v-for="c in casos" :key="c.codcli"><button class="min-h-11 w-full break-words rounded border p-3 text-left" @click="abrirCaso(c.codcli)">{{c.nombre_alumno||c.codcli}} · {{c.nombre_carrera||'Sin carrera'}}</button></li></ul><p v-if="!casos.length&&!errorCasos" class="text-sm">Sin casos accesibles para este filtro</p><div class="flex flex-wrap items-center gap-3"><button class="min-h-11 rounded border px-3 disabled:opacity-40" :disabled="pagina===0" @click="pagina--;cargarCasos()">Anterior</button><span>{{totalCasos?pagina*20+1:0}}–{{Math.min((pagina+1)*20,totalCasos)}} / {{totalCasos}}</span><button class="min-h-11 rounded border px-3 disabled:opacity-40" :disabled="(pagina+1)*20>=totalCasos" @click="pagina++;cargarCasos()">Siguiente</button></div></section>
  </template>
  <SeguimientoCasoDrawer v-if="caso" :caso="caso" :bitacora="bitacora" :anio="drawerPeriodo.anio" :semestre="drawerPeriodo.semestre" @cerrar="caso=null" @agregar-nota="nota=true" @enviado="actualizarCaso" />
  <SeguimientoNotaDialog v-model:open="nota" :guardando="guardandoNota" :error="errorNota" @guardar="guardarNota" />
 </main>
</template>
